import torch
import torch._dynamo

@torch.compile
def f(x):
    return x.sin() + x.cos()

for n in [128, 256, 512]:
    x = torch.randn(n, 64, device="cuda")
    torch._dynamo.mark_dynamic(x, 0)   # mark dim 0 as dynamic
    f(x)

# TORCH_LOGS="recompiles" shows one compile (no recompile on the second or third call).
